"use client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Feedback } from "@/components/forms";
import { commonRoles, normalizeRole, roleShortcutHelp } from "@/lib/roles";
import { useRoleSuggestions } from "@/components/role-allowance";
import { useRolePreferences } from "@/components/use-role-preferences";
export { commonRoles } from "@/lib/roles";
export function RoleChoices({
  roles,
  onChoose,
  disabled = false,
}: {
  roles: string[];
  onChoose: (role: string) => void;
  disabled?: boolean;
}) {
  if (!roles.length) return null;
  return (
    <div className="flex flex-wrap gap-2">
      {roles.map((role) => (
        <Button
          key={role}
          type="button"
          variant="outline"
          className="chip min-h-11 max-w-full whitespace-normal wrap-anywhere [border:1px_dashed_var(--border)] rounded-full [background:transparent] text-link [font:500_12px_ui-monospace,_monospace] h-auto py-2"
          disabled={disabled}
          onClick={() => onChoose(role)}
        >
          {role}
        </Button>
      ))}
    </div>
  );
}
export function Preferences({
  roles,
  setup = false,
}: {
  roles: string[];
  setup?: boolean;
}) {
  const { inputRef, ...draft } = useRolePreferences(roles);
  const { list, suggestions } = useRoleSuggestions();
  return (
    <section className="panel mb-6 space-y-4 p-6">
      <h2 className="section-label [font:600_11px/1.5_ui-monospace,_monospace] tracking-[0.14em] uppercase text-body">
        {setup ? "Choose Your Preferred Roles" : "Outreach Preferences"}
      </h2>
      <p className="text-sm text-body">{roleShortcutHelp(draft.plan)}</p>
      <RoleChoices
        roles={commonRoles.filter(
          (role) =>
            !draft.values.some(
              (value) => normalizeRole(value) === normalizeRole(role),
            ),
        )}
        onChoose={draft.toggle}
        disabled={draft.pending || draft.atLimit}
      />
      <div className="flex flex-wrap gap-2">
        {draft.values.map((role) => (
          <div key={role} className="flex max-w-full items-center gap-1">
            <Button
              type="button"
              variant="outline"
              className="chip min-h-11 max-w-full whitespace-normal wrap-anywhere [border:1px_dashed_var(--border)] rounded-full [background:transparent] text-link [font:500_12px_ui-monospace,_monospace] h-auto py-2"
              disabled={draft.pending}
              onClick={() => draft.toggle(role)}
              aria-label={`Remove ${role}`}
            >
              {role} ×
            </Button>
            <Button
              type="button"
              variant="ghost"
              disabled={draft.pending}
              aria-label={`Edit ${role}`}
              onClick={() => draft.edit(role)}
            >
              Edit
            </Button>
          </div>
        ))}
      </div>
      <p className="text-sm text-body" aria-live="polite">
        {draft.values.length} of {draft.limit} roles selected
      </p>
      <form
        className="space-y-4"
        onSubmit={(event) => {
          event.preventDefault();
          draft.save();
        }}
      >
        <label htmlFor="preferred-custom-role" className="block text-sm">
          Custom role
        </label>
        {draft.editing !== null && (
          <p className="text-sm text-body">Editing {draft.editing}</p>
        )}
        <div className="flex flex-col gap-2.5 sm:flex-row">
          <Input
            id="preferred-custom-role"
            className="h-11 min-w-0 flex-1"
            ref={inputRef}
            aria-invalid={!!draft.error}
            aria-describedby={`preference-role-help${draft.error ? " preference-role-error" : ""}`}
            name="customRole"
            list={list}
            value={draft.custom}
            maxLength={160}
            autoComplete="off"
            disabled={draft.pending}
            onChange={(event) => draft.change(event.target.value)}
            onKeyDown=[REDACTED_SECRET]
              if (event.key === "Escape" && draft.editing !== null) {
                event.preventDefault();
                draft.cancel();
              }
            }}
          />
          <Button
            className="h-11"
            type="button"
            variant="outline"
            disabled={
              draft.pending || (draft.editing === null && draft.atLimit)
            }
            onClick={() => draft.add()}
          >
            {draft.editing !== null ? "Update role" : "Add role"}
          </Button>
          {draft.editing !== null && (
            <Button
              className="h-11"
              type="button"
              variant="outline"
              disabled={draft.pending}
              onClick={draft.cancel}
            >
              Cancel
            </Button>
          )}
        </div>
        <p id="preference-role-help" className="text-xs text-body">
          {draft.values.length > draft.limit
            ? `Remove roles until ${draft.limit} remain before replacing a role.`
            : "To replace a role, choose Edit or remove it and add another."}
        </p>
        {draft.error && (
          <p
            id="preference-role-error"
            role="alert"
            className="text-xs text-error-deep"
          >
            {draft.error}
          </p>
        )}
        {suggestions}
        <Feedback result={draft.result} inlineFieldErrors />
        <Button type="submit" disabled={draft.pending}>
          {draft.pending ? "Saving…" : "Save Preferences"}
        </Button>
      </form>
    </section>
  );
}
